import{_ as t}from"./chunks/image12.BRgDBKom.js";import{_ as o,o as i,c as n,am as a}from"./chunks/framework.CenUaW7a.js";const r="/projects/AiMechaM1/en/advanced-kit/assets/image1.D-_1OfgS.webp",s="/projects/AiMechaM1/en/advanced-kit/assets/image2.D0iHV1f1.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.DDG4vVAP.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.cHuCQ0Yd.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image5.CldLzyxO.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image6.uwOQOvsG.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image7.CJflxfOx.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image8.DfWtEMvT.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image9.CPNovulJ.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image10.DS9pbnKn.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image12.z-xExsqp.png",b="/projects/AiMechaM1/en/advanced-kit/assets/image11.i5Zj-9rq.png",y="/projects/AiMechaM1/en/advanced-kit/assets/image13.DLm9Z0gR.png",P=JSON.parse('{"title":"3.17 Lesson 17: Multi-Color Recognition","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.17 Lesson 17 Multi-Color Recognition.md","filePath":"docs/3. Course materials/3.17 Lesson 17 Multi-Color Recognition.md"}'),v={name:"docs/3. Course materials/3.17 Lesson 17 Multi-Color Recognition.md"};function w(_,e,x,C,k,M){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-17-lesson-17-multi-color-recognition" tabindex="-1">3.17 Lesson 17: Multi-Color Recognition <a class="header-anchor" href="#_3-17-lesson-17-multi-color-recognition" aria-label="Permalink to &quot;3.17 Lesson 17: Multi-Color Recognition&quot;">​</a></h1><h2 id="_3-17-1-lesson-introduction" tabindex="-1">3.17.1 Lesson Introduction <a class="header-anchor" href="#_3-17-1-lesson-introduction" aria-label="Permalink to &quot;3.17.1 Lesson Introduction&quot;">​</a></h2><p>Inspired by automated fruit sorting, this lesson bridges human color perception with machine RGB recognition, introducing the K230 module hardware and its library of over 30 AI vision functions. By mastering core operations such as vision initialization, multi-color detection, and real-time data updating, students enable the car to identify red, green, and blue objects and trigger matching RGB LEDs in a seamless &quot;what you see is what lights up&quot; interaction. Serving as the foundation for AI vision, this lesson establishes a unified programming paradigm of &quot;initialization, detection, data updating, and conditional evaluation&quot; for subsequent courses such as face recognition.</p><h2 id="_3-17-2-learning-objectives" tabindex="-1">3.17.2 Learning Objectives <a class="header-anchor" href="#_3-17-2-learning-objectives" aria-label="Permalink to &quot;3.17.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the RGB three-channel principle of machine vision color recognition and master the fundamental concept of pixel brightness analysis. Learn the dual-module architecture of the K230 split-type vision module, which pairs a camera with a screen processor, along with the advantages of its split design.</p><p><strong>2.</strong> Independently complete the hardware installation of the K230 split-type module and wire it to port A. Proficiently master the three-step initialization workflow of port initialization, mode configuration, and detection startup.</p><p><strong>3.</strong> Establish a three-layer machine vision architectural mindset of visual perception, AI processing, and command output. Cultivate modular programming habits and master the standard program structure of initialization, main loop, and conditional response.</p><p><strong>4.</strong> Connect color vision technology to real-world application scenarios such as color sorters, smart shelves, traffic light recognition, and industrial optical sorting machines, understanding its broad value in industrial automation and daily life.</p><h2 id="_3-17-3-preparation" tabindex="-1">3.17.3 Preparation <a class="header-anchor" href="#_3-17-3-preparation" aria-label="Permalink to &quot;3.17.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C USB data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Hardware Structure Description:</strong></p><ul><li><p><strong>HD Camera Module</strong>: Captures images like the eyes of the robot and is mounted at the front of the car.</p></li><li><p><strong>K230 Screen Module</strong>: Features a built-in AI processor for image analysis and computation, mounted in the middle of the car body.</p></li><li><p>The two modules are connected via a data cable, featuring a split design that allows flexible installation without mutual interference.</p></li></ul><p><strong>Wiring Instructions:</strong></p><ul><li><p>Connect the K230 screen module to port A of the controller using a serial cable.</p></li><li><p>Connect the camera module to the camera port on the screen module using the dedicated ribbon cable.</p></li><li><p>Mount the camera facing forward and the screen facing upward for easy observation of recognition results.</p></li></ul><p><strong>Color Recognition Mode Categories:</strong></p><ul><li><p><strong>Single-Color Detection</strong>: Detects only one specified color, suitable for simple scenarios.</p></li><li><p><strong>Multi-Color Detection</strong>: Simultaneously detects multiple preset colors, which is the mode used in this lesson.</p></li><li><p><strong>Color Self-Learning</strong>: Learns and names custom colors, suitable for specialized color targets.</p></li></ul><h2 id="_3-17-4-hands-on-project" tabindex="-1">3.17.4 Hands-On Project <a class="header-anchor" href="#_3-17-4-hands-on-project" aria-label="Permalink to &quot;3.17.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This lesson builds a machine vision system based on &quot;visual perception, real-time detection, and status feedback&quot;. The split camera transmits images via the ribbon cable to the K230 processor, where AI algorithms analyze RGB values pixel by pixel to identify red, green, and blue color blocks along with their coordinates and confidence scores, synchronizing the results across the onboard RGB LEDs and ultrasonic RGB lights. The program follows the four-step K230 paradigm: initialize the communication port, select multi-color detection mode, start detection, and turn off the lights. In each frame of the main loop, the controller updates and caches the latest results, sequentially checking for red, green, or blue detections to illuminate the corresponding lights. Operating at approximately 30 frames per second, the system achieves real-time &quot;color-triggered lighting&quot; interaction.</p><img loading="lazy" height="442" width="960" src="'+r+'" class="common_img" style="width:600px;aspect-ratio:960 / 442;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="565" width="805" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:805 / 565;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Module initialization</td><td style="text-align:center;"><img loading="lazy" height="81" width="419" src="'+l+'" class="common_img" style="width:300px;aspect-ratio:419 / 81;"></td><td style="text-align:left;">Configures the communication port of the K230 module to establish a serial connection between the controller and the vision module.</td></tr><tr><td style="text-align:center;">Mode configuration</td><td style="text-align:center;"><img loading="lazy" height="84" width="593" src="'+c+'" class="common_img" style="width:300px;aspect-ratio:593 / 84;"></td><td style="text-align:left;">Switches the operating mode of the vision module to select the color recognition function.</td></tr><tr><td style="text-align:center;">Detection control</td><td style="text-align:center;"><img loading="lazy" height="86" width="300" src="'+d+'" class="common_img" style="width:140px;aspect-ratio:300 / 86;"></td><td style="text-align:left;">Starts the vision detection engine so the module begins capturing images and running AI algorithms.</td></tr><tr><td style="text-align:center;">Data update</td><td style="text-align:center;"><img loading="lazy" height="86" width="408" src="'+h+'" class="common_img" style="width:200px;aspect-ratio:408 / 86;"></td><td style="text-align:left;">Reads the latest recognition results from the vision module and synchronizes them to the controller cache.</td></tr><tr><td style="text-align:center;">Color detection</td><td style="text-align:center;"><img loading="lazy" height="66" width="448" src="'+p+'" class="common_img" style="width:200px;aspect-ratio:448 / 66;"></td><td style="text-align:left;">Determines whether a specified color appears in the frame and returns a boolean value for conditional evaluation.</td></tr><tr><td style="text-align:center;">Color parameters</td><td style="text-align:center;"><img loading="lazy" height="271" width="513" src="'+g+'" class="common_img" style="width:200px;aspect-ratio:513 / 271;"></td><td style="text-align:left;">Reads detailed information about the target color, including name, confidence, <code>x</code> and <code>y</code> coordinates, width, and height.</td></tr><tr><td style="text-align:center;">Light control</td><td style="text-align:center;"><img loading="lazy" height="77" width="293" src="'+m+'" class="common_img" style="width:160px;aspect-ratio:293 / 77;"></td><td style="text-align:left;">Controls the display color of the onboard RGB LEDs on the controller board.</td></tr><tr><td style="text-align:center;">Light control</td><td style="text-align:center;"><img loading="lazy" height="72" width="445" src="'+u+'" class="common_img" style="width:200px;aspect-ratio:445 / 72;"></td><td style="text-align:left;">Controls the full-color LED beads on the ultrasonic module.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Recognizing Red and Illuminating Red Lights</strong></p><ul><li><p>Initialization settings: At startup, execute the <code>Initialization module at A</code> to establish communication, execute <code>Set Operating mode Multi-color detection</code> to switch to color recognition mode, execute <code>Start Run Test</code> to enable the vision engine, and turn off both the onboard RGB LEDs and the ultrasonic sensor RGB lights to establish an initial off state.</p></li><li><p>Main loop structure: Enter the repeat <code>forever</code> main loop and execute <code>Update and save result data</code> as the very first step to synchronize the latest detection results from the vision module to the controller, which is a mandatory step for all K230 programs.</p></li><li><p>Conditional evaluation: Add an <code>if Is the color detected as red then</code> branch containing two commands to set the onboard RGB LED color to red and set all LED beads on the ultrasonic sensor to red.</p></li><li><p>Program outcome: When a red object is placed in front of the camera, both sets of RGB lights illuminate red simultaneously. Because there is no else branch to turn off the lights, the lights remain red after the red object is removed, which is refined in Task 2.</p></li></ul><img loading="lazy" height="266" width="399" src="'+f+'" class="common_img" style="width:430px;aspect-ratio:399 / 266;"><img loading="lazy" height="288" width="395" src="'+b+'" class="common_img" style="width:400px;aspect-ratio:395 / 288;"><p><strong>Task 2: Adding Green and Blue Recognition for Three-Color Synchronization</strong></p><ul><li><p>Expand conditional branches: Following the red detection branch, add two independent conditional branches to illuminate green lights when green is detected and illuminate blue lights when blue is detected.</p></li><li><p>Parallel three-color detection: The three color evaluations operate independently and respond sequentially if multiple colors appear in the frame simultaneously. Because the human eye perceives the final triggered color state, keeping only one target color in the frame during testing is recommended.</p></li><li><p>Complete program workflow: Initialize at startup → turn off all lights → repeat forever to update data → check for red to illuminate red lights → check for green to illuminate green lights → and check for blue to illuminate blue lights.</p></li><li><p>Debugging method: Present red, green, and blue objects to the camera sequentially and verify whether the corresponding lights illuminate. If the lights fail to respond, check for loose wiring, incorrect mode settings, or a missing data update command.</p></li></ul><p><strong>K230 Module Programming Notes</strong></p><ul><li><p>Initialize the communication port first, configure the running mode second, and start detection last without reversing the order.</p></li><li><p>Place the <code>Update and save result data</code> command before all conditional evaluations inside the main loop and execute it once per cycle. Otherwise, the program evaluates outdated data from the previous frame.</p></li><li><p>Reconfigure the running mode whenever switching functions, as color detection and face recognition cannot run simultaneously.</p></li><li><p>Lighting conditions significantly affect recognition performance, so avoid direct strong light or backlighting and test under uniform ambient light for optimal accuracy.</p></li><li><p>Preview the live camera feed and recognition bounding boxes on the split-module screen for intuitive debugging.</p></li></ul><img loading="lazy" height="561" width="424" src="'+y+'" class="common_img" style="width:390px;aspect-ratio:424 / 561;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Multi-Color Recognition</a>.</strong></p></div><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+t+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-17-5-expansion-and-advancement" tabindex="-1">3.17.5 Expansion and Advancement <a class="header-anchor" href="#_3-17-5-expansion-and-advancement" aria-label="Permalink to &quot;3.17.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Color-Triggered Intelligent Transport System</strong></p><p>Combine color recognition with robotic arm handling to design a color sorting system where the car drives forward to grasp a red block and transports it to the red zone, or transports a blue block to the blue zone. Incorporate line-following navigation to achieve multi-station automated delivery, simulating a warehouse color-sorting assembly line and demonstrating how machine vision drives complete automated workflows.</p><p><strong>Expansion Project 2: Custom Color Learning and Multi-Color Classification Counting</strong></p><p>Use the color self-learning function on the K230 module to learn custom colors such as orange, purple, and yellow, expanding the recognizable color categories to more than eight. Add counter variables to track the occurrences of each color and use different buzzer pitches to indicate color categories, achieving multi-color classification and counting that simulates an industrial optical color sorter.</p><h2 id="_3-17-6-q-a" tabindex="-1">3.17.6 Q&amp;A <a class="header-anchor" href="#_3-17-6-q-a" aria-label="Permalink to &quot;3.17.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why is the K230 vision module designed as a split-type system?</strong></p><p><strong>Answer</strong>: The core advantages of a split-type design are <strong>installation flexibility and ergonomic optimization</strong>, which represent a standard architecture in industrial machine vision equipment.</p><p><strong>Q2: Why must the <code>Update and save result data</code> command be executed before making conditional evaluations in the main loop?</strong></p><p><strong>Answer</strong>: The K230 module and the controller are <strong>two independently operating processors</strong> that exchange data via serial communication rather than shared memory. While the vision module continuously runs detection algorithms and generates dozens of new frames per second independently, the controller does not receive these updates automatically and must actively issue a command to fetch the latest result data in each loop cycle.</p><h2 id="_3-17-7-technical-support-and-discussion" tabindex="-1">3.17.7 Technical Support and Discussion <a class="header-anchor" href="#_3-17-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.17.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',53)])])}const q=o(v,[["render",w]]);export{P as __pageData,q as default};
